$limit = 12;
$offset = 0;
$audited = 0;
$allFindings = [];
$mediaCache = [];
while (true) {
    $list = $tools->call("cms_list_articles", ["offset"=>$offset, "limit"=>$limit]);
    if (!isset($list->items) || !is_array($list->items)) {
        break;
    }
    $articleIds = [];
    foreach ($list->items as $item) {
        $articleIds[] = $item->id;
    }
    if (empty($articleIds)) {
        break;
    }
    $articlesResp = $tools->call("cms_get_articles", ["ids"=>$articleIds]);
    $mediaToFetch = [];
    $articleMap = [];
    foreach ($articlesResp->items as $article) {
        $audited++;
        $issues = [];
        if (empty($article->meta_description)) {
            $issues[] = "missing_description";
        }
        $imageId = $article->image_id ?? null;
        if ($imageId) {
            if (!array_key_exists($imageId, $mediaCache)) {
                $mediaToFetch[] = $imageId;
            }
            $articleMap[$article->id] = ["title"=>$article->title, "issues"=>$issues, "image_id"=>$imageId];
        } else {
            if (!empty($issues)) {
                $allFindings[] = ["id"=>$article->id, "title"=>$article->title, "issues"=>$issues];
            }
        }
    }
    if (!empty($mediaToFetch)) {
        $mediaResp = $tools->call("cms_get_media", ["ids"=>$mediaToFetch]);
        foreach ($mediaResp->items as $media) {
            $mediaCache[$media->id] = $media;
        }
    }
    foreach ($articleMap as $aid => $info) {
        $issues = $info["issues"];
        $imageId = $info["image_id"];
        $media = $mediaCache[$imageId] ?? null;
        if ($media && empty($media->alt)) {
            $issues[] = "missing_alt";
        }
        if (!empty($issues)) {
            $allFindings[] = ["id"=>$aid, "title"=>$info["title"], "issues"=>$issues];
        }
    }
    if ($list->next_offset === null) {
        break;
    }
    $offset = $list->next_offset;
}
usort($allFindings, function($a,$b){return $a["id"] <=> $b["id"];});
return ["audited"=>$audited, "findings"=>$allFindings];

