$offset = 0;
$limit = 12;
$allArticles = [];
do {
    $listResp = $tools->call('cms_list_articles', ['offset' => $offset, 'limit' => $limit]);
    if (!isset($listResp->items) || !is_array($listResp->items)) {
        break;
    }
    foreach ($listResp->items as $item) {
        $allArticles[] = ['id' => $item->id, 'title' => $item->title];
    }
    $next = $listResp->next_offset ?? null;
    if ($next === null) {
        break;
    }
    $offset = $next;
} while (true);

$totalAudited = count($allArticles);

// Fetch article metadata in batches
$articleData = [];
$imageIds = [];
for ($i = 0; $i < $totalAudited; $i += 12) {
    $batchIds = array_slice(array_column($allArticles, 'id'), $i, 12);
    $resp = $tools->call('cms_get_articles', ['ids' => $batchIds]);
    if (!isset($resp->items) || !is_array($resp->items)) continue;
    foreach ($resp->items as $art) {
        $articleData[$art->id] = [
            'id' => $art->id,
            'title' => $art->title,
            'meta_description' => $art->meta_description ?? '',
            'image_id' => $art->image_id ?? null,
        ];
        if (!empty($art->image_id)) {
            $imageIds[$art->image_id] = true;
        }
    }
}

// Fetch media metadata for image ids
$mediaMap = [];
$imageIdList = array_keys($imageIds);
for ($i = 0; $i < count($imageIdList); $i += 12) {
    $batch = array_slice($imageIdList, $i, 12);
    $resp = $tools->call('cms_get_media', ['ids' => $batch]);
    if (!isset($resp->items) || !is_array($resp->items)) continue;
    foreach ($resp->items as $media) {
        $mediaMap[$media->id] = $media->alt ?? '';
    }
}

$findings = [];
foreach ($articleData as $aid => $ad) {
    $issues = [];
    if (trim($ad['meta_description']) === '') {
        $issues['missing_description'] = true;
    }
    $imgId = $ad['image_id'];
    if ($imgId !== null) {
        $alt = $mediaMap[$imgId] ?? null;
        if ($alt === null || trim($alt) === '') {
            $issues['missing_alt'] = true;
        }
    }
    if (!empty($issues)) {
        $findings[] = [
            'id' => $ad['id'],
            'title' => $ad['title'],
            'issues' => $issues,
        ];
    }
}

usort($findings, function($a, $b) { return $a['id'] <=> $b['id']; });

return ['audited' => $totalAudited, 'findings' => $findings];

