$limit = 12;
$offset = 0;
$articles = [];
do {
    $resp = $tools->call("cms_list_articles", ["offset"=>$offset, "limit"=>$limit]);
    if (!isset($resp->items) || !is_array($resp->items)) {
        return ["error"=>"coverage_error","message"=>"Failed to list articles"];
    }
    foreach ($resp->items as $item) {
        $articles[] = ["id"=>$item->id, "title"=>$item->title];
    }
    $next = $resp->next_offset;
    if ($next === null) {
        break;
    }
    $offset = $next;
} while (true);
$total = count($articles);
$articleData = [];
for ($i=0;$i<$total;$i+= $limit) {
    $ids = array_slice(array_column($articles, "id"), $i, $limit);
    $resp = $tools->call("cms_get_articles", ["ids"=>$ids]);
    if (!isset($resp->items) || !is_array($resp->items)) {
        return ["error"=>"coverage_error","message"=>"Failed to get article metadata"];
    }
    foreach ($resp->items as $a) {
        $articleData[$a->id] = $a;
    }
}
if (count($articleData) != $total) {
    return ["error"=>"coverage_error","message"=>"Missing article metadata"];
}
$imageIds = [];
foreach ($articleData as $a) {
    if (!empty($a->image_id)) {
        $imageIds[$a->image_id] = true;
    }
}
$imageIds = array_keys($imageIds);
$mediaData = [];
for ($i=0;$i<count($imageIds);$i+= $limit) {
    $ids = array_slice($imageIds, $i, $limit);
    if (empty($ids)) continue;
    $resp = $tools->call("cms_get_media", ["ids"=>$ids]);
    if (!isset($resp->items) || !is_array($resp->items)) {
        return ["error"=>"coverage_error","message"=>"Failed to get media"];
    }
    foreach ($resp->items as $m) {
        $mediaData[$m->id] = $m;
    }
}
foreach ($imageIds as $iid) {
    if (!isset($mediaData[$iid])) {
        return ["error"=>"coverage_error","message"=>"Missing media for image_id $iid"];
    }
}
$findings = [];
ksort($articleData);
foreach ($articleData as $a) {
    $issues = [];
    if (empty($a->meta_description)) {
        $issues[] = "missing_description";
    }
    if (!empty($a->image_id)) {
        $media = $mediaData[$a->image_id] ?? null;
        if ($media && empty($media->alt)) {
            $issues[] = "missing_alt";
        }
    }
    if (!empty($issues)) {
        $findings[] = ["id"=>$a->id, "title"=>$a->title, "issues"=>$issues];
    }
}
return ["audited"=>$total, "findings"=>$findings];

