$offset = 0;
$limit = 12;
$audited = 0;
$findings = [];
$mediaCache = [];
while (true) {
    $list = $tools->call("cms_list_articles", ["offset"=>$offset, "limit"=>$limit]);
    if (!isset($list->items) || count($list->items)===0) {
        break;
    }
    $articleIds = [];
    foreach ($list->items as $item) {
        $articleIds[] = $item->id;
    }
    $articlesResp = $tools->call("cms_get_articles", ["ids"=>$articleIds]);
    $articles = $articlesResp->items ?? [];
    $neededImageIds = [];
    foreach ($articles as $article) {
        if (isset($article->image_id) && $article->image_id !== null && !isset($mediaCache[$article->image_id])) {
            $neededImageIds[] = $article->image_id;
        }
    }
    $batchSize = 12;
    for ($i=0;$i<count($neededImageIds);$i+=$batchSize) {
        $batch = array_slice($neededImageIds,$i,$batchSize);
        $mediaResp = $tools->call("cms_get_media", ["ids"=>$batch]);
        foreach ($mediaResp->items ?? [] as $media) {
            $mediaCache[$media->id] = $media;
        }
    }
    foreach ($articles as $article) {
        $audited++;
        $issues = [];
        $desc = $article->meta_description ?? "";
        if (trim($desc) === "") {
            $issues[] = "missing_description";
        }
        if (isset($article->image_id) && $article->image_id !== null) {
            $imgId = $article->image_id;
            if (isset($mediaCache[$imgId])) {
                $alt = $mediaCache[$imgId]->alt ?? "";
                if (trim($alt) === "") {
                    $issues[] = "missing_alt";
                }
            }
        }
        if (!empty($issues)) {
            $findings[] = (object)[
                "id"=>$article->id,
                "title"=>$article->title,
                "issues"=>$issues
            ];
        }
    }
    if (!property_exists($list, "next_offset") || $list->next_offset===null) {
        break;
    }
    $offset = $list->next_offset;
}
usort($findings, function($a,$b){return $a->id <=> $b->id;});
return (object)[
    "audited"=>$audited,
    "findings"=>$findings
];

